    @EventHandler
    public void on( DeleteMessagingEndpointEvent event) {
    	MessagingEndpoint entity = new MessagingEndpoint();
   
    	// ------------------------------------------
    	// apply the MessagingEndpointId
    	// ------------------------------------------
    	entity.setMessagingEndpointId( event.getMessagingEndpointId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
